import re
did=re.search(r'data-id="(\d+)" data-title="Kerala Flood Test"',b.last) or re.search(r'data-id="(\d+)" data-title="Kerala',b.last)
b.get('/app/disasters'); did=re.search(r'data-id="(\d+)" data-title="Kerala Flood Test"',b.last).group(1)
b.post('/app/disasters',{'action':'status','id':did,'status':'ACTIVE'}); check('status update',b.alert() and b.alert()[0]=='success',b.alert())
b.post('/app/disasters',{'action':'update','id':did,'title':'Kerala Flood Test','type':'FLOOD','severity':'CATASTROPHIC','location':'Malappuram','population':'15000','start':'2026-10-01T08:00','end':'','description':'x'})
