b.post('/app/victims',{'action':'create','_modal':'createVictim','fullName':'Anil Kumar','age':'45','gender':'MALE','phone':'9876543210','emergencyStatus':'CRITICAL','currentLocation':'Nilambur','disasterId':did,'medicalCondition':'fracture','familyInfo':''})
